import numpy as np

from mcf.research.arena.indicators import compute

SIDE = 'short'
GEOM = 'hold'
WINDOW = (1100, 1300)          # bar close lo <= tod <= hi (inclusive, as the YAML window)
MIN_ADV = 150000000.0
CONTEXT = ['breadth_open']              # lab context columns (config `context:`), point-in-time per 5-minute bar
CONDS = [
    ('breadth_open', '<', 0.35),
    ('day_vs_prev_range', '<=', 0.34),
    ('rsi5', '<=', 13.0),
    ('vwap_atr', '<=', -0.15),
]
LAYERS = ['breadth_open < 0.35', 'day_vs_prev_range <= 0.34', 'rsi5 <= 13', 'vwap_atr <= -0.15', 'window 1100-1300']


def mask(df) -> np.ndarray:
    x = compute(df, names=['day_vs_prev_range', 'rsi5', 'vwap_atr'], context=False)
    tod = df["tod"].to_numpy(dtype=float)
    m = (tod >= WINDOW[0]) & (tod <= WINDOW[1])
    with np.errstate(invalid="ignore"):
        for nm, op, v in CONDS:
            if nm in CONTEXT:
                a = df[nm].to_numpy(dtype=float) if nm in df.columns else np.full(len(df), np.nan)
            else:
                a = x[nm].to_numpy(dtype=np.float32).astype(float)
                v = float(np.float32(v))
            if op == "<=":
                m &= a <= v
            elif op == "<":
                m &= a < v
            elif op == ">=":
                m &= a >= v
            elif op == ">":
                m &= a > v
            else:
                m &= a == v
    return np.asarray(m, dtype=bool)
